package dev.pocketengine.runtime.usage;
import java.time.Instant;
import java.util.UUID;
import org.json.*;
import org.junit.Test;
import static org.junit.Assert.*;
public final class InferenceTrendQueryTest {
 private static final long FROM=Instant.parse("2026-10-31T00:00:00Z").toEpochMilli(),UNTIL=Instant.parse("2026-11-03T00:00:00Z").toEpochMilli();
 private static JSONObject receipt(long at,boolean known)throws Exception {ProviderUsage.Collector usage=new ProviderUsage.Collector("openai_chat");if(known)usage.observe(new JSONObject().put("usage",new JSONObject().put("prompt_tokens",2).put("completion_tokens",3).put("total_tokens",5)),ProviderUsage.Stage.FINAL);return new JSONObject().put("type","inference_receipt").put("receiptVersion",1).put("evidenceOnly",true).put("callId",UUID.randomUUID().toString()).put("outcome","COMPLETED").put("startedAt",at).put("context",new JSONObject().put("taskId",UUID.randomUUID().toString()).put("runId",UUID.randomUUID().toString()).put("purpose","MAIN").put("memberId",""))
  .put("route",new JSONObject().put("kind","api_key").put("connectionId","deleted-provider-original-id").put("protocol","openai_chat").put("requestedModel","original-model")).put("usage",usage.toJson());}
 private static long known(JSONObject usage)throws Exception{return usage.getJSONArray("groups").getJSONObject(0).getJSONObject("counters").getJSONObject("TOTAL").getLong("knownSubtotal");}
 @Test public void timezoneMovesDaysWithoutRepricingOrChangingOriginalTotals()throws Exception {JSONObject a=receipt(Instant.parse("2026-11-01T23:30:00Z").toEpochMilli(),true),b=receipt(Instant.parse("2026-11-02T00:30:00Z").toEpochMilli(),true);JSONArray source=new JSONArray().put(a).put(b).put(new JSONObject(a.toString()));String before=source.toString();JSONObject utc=InferenceTrendQuery.report(source,FROM,UNTIL,"UTC"),sh=InferenceTrendQuery.report(source,FROM,UNTIL,"Asia/Shanghai");assertEquals(2,utc.getJSONObject("total").getInt("attempts"));assertEquals(10,known(utc.getJSONObject("total")));assertEquals(10,known(sh.getJSONObject("total")));assertEquals(2,utc.getJSONArray("daily").length());assertEquals(1,sh.getJSONArray("daily").length());assertEquals("deleted-provider-original-id",sh.getJSONArray("breakdown").getJSONObject(0).getString("historicalProviderId"));assertEquals(before,source.toString());}
 @Test public void unknownIsNotFreeAndDailyTotalsUseTheSameNativeProjection()throws Exception {JSONArray events=new JSONArray().put(receipt(FROM+1000,true)).put(receipt(FROM+2000,false));JSONObject report=InferenceTrendQuery.report(events,FROM,UNTIL,"UTC");JSONObject total=report.getJSONObject("total"),daily=report.getJSONArray("daily").getJSONObject(0).getJSONObject("usage");assertEquals(known(total),known(daily));assertEquals(1,total.getJSONArray("groups").getJSONObject(0).getJSONObject("counters").getJSONObject("TOTAL").getInt("unknownCalls"));assertTrue(total.isNull("actualCost"));assertFalse(report.getBoolean("unknownIsZero"));}
 @Test public void conflictingReceiptCannotBecomeTrustedWhenRegrouped()throws Exception {JSONObject first=receipt(FROM+1000,true),second=new JSONObject(first.toString());second.getJSONObject("usage").getJSONObject("counters").getJSONObject("TOTAL").put("value",50);JSONObject report=InferenceTrendQuery.report(new JSONArray().put(first).put(second),FROM,UNTIL,"UTC");assertEquals(1,report.getJSONObject("total").getInt("conflictingCalls"));JSONObject day=report.getJSONArray("daily").getJSONObject(0).getJSONObject("usage");assertEquals(1,day.getInt("conflictingCalls"));assertEquals(0,day.getJSONArray("groups").length());}
}
